<div class="data-panel"><div class="data-panel__toolbar"><form method="get" action="<?= BASE_URL ?>staff/index" id="filtrosEmpleados" class="data-panel__filters"><select name="cargo" class="form-select" aria-label="Filtrar por cargo"><option value="">Tipo (Todos)</option><?php foreach ($cargos as $cargo): ?><option value="<?= (int) $cargo['id'] ?>" <?= (string) ($_GET['cargo'] ?? '') === (string) $cargo['id'] ? 'selected' : '' ?>><?= htmlspecialchars($cargo['nombre']) ?></option><?php endforeach; ?></select><select name="estado" class="form-select" aria-label="Filtrar por estado"><option value="">Estado (Todos)</option><option value="activo" <?= ($_GET['estado'] ?? '') === 'activo' ? 'selected' : '' ?>>Activo</option><option value="inactivo" <?= ($_GET['estado'] ?? '') === 'inactivo' ? 'selected' : '' ?>>Inactivo</option></select><div class="data-panel__search"><i class="bi bi-search"></i><input type="search" name="q" class="form-control" placeholder="Buscar por nombre, cédula o cargo..." value="<?= htmlspecialchars($_GET['q'] ?? '') ?>" autocomplete="off"></div></form></div><div class="data-panel__body"><table class="data-panel__table"><colgroup><col style="width:30%"><col style="width:18%"><col style="width:22%"><col style="width:14%"><col style="width:16%"></colgroup><thead><tr><th>Empleado</th><th>Cédula</th><th>Cargo</th><th>Estado</th><th class="text-center">Acciones</th></tr></thead><tbody id="tablaEmpleadosBody"><?php foreach ($empleados as $empleado): ?><tr class="<?= $empleado['estado'] === 'inactivo' ? 'is-muted' : '' ?>"><td><div class="avatar-group"><span class="avatar avatar--md avatar--primary"><?= htmlspecialchars($empleado['iniciales']) ?></span><span class="avatar-group__name"><?= htmlspecialchars($empleado['nombre']) ?></span></div></td><td class="text-support"><?= htmlspecialchars($empleado['cedula']) ?></td><td class="text-support"><?= htmlspecialchars($empleado['cargo']) ?></td><td><span class="status-badge status-badge--<?= $empleado['estado'] === 'activo' ? 'active' : 'inactive' ?>"><?= ucfirst($empleado['estado']) ?></span></td><td class="text-center"><div class="data-panel__actions"><button type="button" class="action-btn action-btn--view btn-ver-empleado" title="Ver detalle" data-id="<?= (int) $empleado['id'] ?>"><i class="bi bi-eye"></i></button><button type="button" class="action-btn action-btn--edit btn-editar-empleado" title="Editar empleado" data-id="<?= (int) $empleado['id'] ?>"><i class="bi bi-pencil"></i></button><div class="form-check form-switch table-switch mb-0"><input class="form-check-input toggle-empleado" type="checkbox" role="switch" data-id="<?= (int) $empleado['id'] ?>" <?= $empleado['estado'] === 'activo' ? 'checked' : '' ?> aria-label="Cambiar estado de <?= htmlspecialchars($empleado['nombre']) ?>"></div></div></td></tr><?php endforeach; ?><?php if (!$empleados): ?><tr><td colspan="5" class="text-center text-support py-4">No se encontraron empleados registrados.</td></tr><?php endif; ?></tbody></table></div><div class="data-panel__footer"><span id="paginacionInfo">Mostrando <?= (int) $paginacion['desde'] ?> a <?= (int) $paginacion['hasta'] ?> de <?= (int) $paginacion['total'] ?> empleados</span><?php $paginacionAriaLabel = 'Paginación de empleados'; require __DIR__ . '/../partials/pagination.php'; ?></div></div>
